mapper.select:
SELECT


	, IF((SELECT idx FROM MEMBER_CONTENT WHERE c.idx = idx_content AND idx_profile = #{idx_profile}), "Y", "N") AS bookmark_yn

FROM
	CONTENT c


	AND c.category = 'MOVIE'


	AND c.category = 'TV'


	AND c.broadcast_date BETWEEN  date_add(now(), interval -1 year) AND now()


	AND (
			c.genre1 = #{genre}
		OR
			c.genre2 = #{genre}
		OR
			c.genre3 = #{genre}
	)


ORDER BY c.idx DESC

LIMIT ${limit} OFFSET ${offset}

mapper.delete:
DELETE FROM
	MEMBER_CONTENT
WHERE
	idx_profile = #{idx_profile}

	AND idx_content = #{idx_content}

mapper.insert:
INSERT INTO
	MEMBER_CONTENT (
		  idx_content
		, idx_profile
	) VALUES (
		  #{idx_content}
		, #{idx_profile}
	)
